type Row = BaseEntity & Record<string, any>
type CellColumn = { id: string; header: string; className?: string; cell: (row: Row) => ReactNode }
type EditorField = { name: string; label: string; type?: 'text' | 'email' | 'number' | 'select' | 'textarea'; required?: boolean; placeholder?: string; options?: (state: DemoState) => Array<{ label: string; value: string }> }
type ResourceSpec = {
  collection: EntityCollection
  title: string
  singular: string
  description: string
  icon: LucideIcon
  codeKey?: string
  nameKey: string
  statusKey?: string
  detailPath: (row: Row) => string
  columns: (state: DemoState) => CellColumn[]
  fields: EditorField[]
  defaults: Record<string, any>
  createPath?: string
}

